    private int count = 0;

    // Adds a name to the end of the waitlist. Returns true if it was added.
    public boolean join(String name)
    {
        // TODO (R2): the same student can't be waiting twice.
        if (count == names.length)
            return false;
        names[count] = name;
        ++count;
        return true;
